// Interactive prototype only. No real records, Drive URLs, credentials, or email connections.
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cash=n=>n===null||n===undefined?'Not confirmed':'₱'+Number(n).toLocaleString('en-PH',{minimumFractionDigits:2,maximumFractionDigits:2});
const date=v=>v?new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Manila'}).format(new Date(v.length===10?v+'T12:00:00+08:00':v)):'Not recorded';
const time=v=>new Intl.DateTimeFormat('en-GB',{day:'numeric',month:'short',year:'numeric',hour:'numeric',minute:'2-digit',timeZone:'Asia/Manila'}).format(new Date(v));
const TODAY='2026-10-11', statusColors={'New request':'new','Missing requirements':'missing','Awaiting reply':'sent','Under review':'review','Approved · unpaid':'approved','Paid':'paid','Denied':'denied'};
let fromDate='',untilDate='';
let clock=0,records=[],messages=[],selected=null,step=1,view='Home',statusFilter='All',search='',mailFilter='Inbox',picked=null,paused=false;
let settings={to:'claims@example.com',cc:'accounting@example.com',sender:'processor@example.com',signature:'RMC2 Reimbursement Team',template:'Good Day!\n\nHi All,\n\nPlease see reimbursement request for {{name}}, attached are the documents needed upon processing.\n\nReference: {{id}}\nType of availment: {{type}}\nDate of availment: {{date}}\nAmount incurred: {{amount}}\n\nShould you have any questions or concerns, please kindly reach out to me.\n\nFor your handling and kind assistance. Thank you.\n\nTHANK YOU & BEST REGARDS,\n{{signature}}'};
const stamp=()=>new Date(new Date(TODAY+'T09:00:00+08:00').getTime()+(clock++)*60000).toISOString();
const button=(s,fn,cl='',disabled=false)=>`<button class="${cl}" onclick="${fn}" ${disabled?'disabled':''}>${s}</button>`;
const badge=s=>`<span class="badge ${statusColors[s]||'sent'}">${esc(s)}</span>`;
const current=()=>records.find(r=>r.id===selected);
const log=(r,text)=>{r.updated=stamp();r.history.unshift({at:r.updated,text});};
const requiredSpecs=[
 ['form','AMAPHIL reimbursement form','Uploaded claim form · check completed fields, bank details, and signatures.'],
 ['incident','Incident letter for reimbursement request','Uploaded incident letter · explains why reimbursement is requested.'],
 ['receipt','Sales invoice / official receipt with BIR TIN','Uploaded receipt(s) · review every receipt in this submission.'],
 ['order','Doctor’s laboratory / diagnostic request','Uploaded doctor’s request · applies to laboratory or diagnostic procedures.'],
 ['abstract','Medical abstract','Uploaded medical abstract · admission cases; confirm applicability.'],
 ['itemized','Itemized breakdown of charges','Uploaded charges breakdown · the claim form specifies inpatient / confinement.'],
 ['medical','Medical certificate / attending physician’s report','Claim form · final diagnosis for inpatient or outpatient laboratory. A completed physician report can substitute.'],
 ['prescription','Doctor’s prescription','Claim form · outpatient medicines.'],
 ['accident','Police report / affidavit of accident','Claim form · police report for vehicular accident, affidavit for other incidents.']
];
function requirementsFor(r){return requiredSpecs.map(([key,title,source])=>({key,title,source,required:['form','incident','receipt'].includes(key)||key==='order'&&r.laboratory||['abstract','itemized'].includes(key)&&r.type==='ADMISSION'||key==='medical'&&(r.type==='ADMISSION'||r.laboratory)||key==='prescription'&&r.medicines||key==='accident'&&r.accident}));}
function newRecord(n,name,type='OPD',amount=8500){let r={id:'RMC2-2026-'+String(n).padStart(5,'0'),name,type,amount,approved:null,reimbursed:null,paidBy:null,paidDate:null,paymentEmail:null,provider:'AMAPHIL',date:'2026-10-02',received:TODAY,updated:stamp(),email:'applicant@example.com',facility:'Sample Medical Center',reason:'Service was paid personally while provider authorization was unavailable.',laboratory:type==='OPD',medicines:false,accident:false,status:'New request',reviewed:false,sentAt:null,followup:null,proposal:null,draft:null,files:[],history:[],notes:[]};requirementsFor(r).filter(q=>q.required).forEach(q=>r.files.push({key:q.key,name:q.title.replaceAll('/','-')+'.pdf',checked:false,selected:true,replacement:false}));r.files.push({key:'receipt',name:'Official receipt 02.jpg',checked:false,selected:true,replacement:false});log(r,'Sample Form submission received.');return r;}
function seed(){clock=0;records=[newRecord(127,'Jamie Santos'),newRecord(126,'Morgan Cruz','ADMISSION',18500),newRecord(125,'Casey Reyes','ER (Emergency)',6250),newRecord(124,'Taylor Garcia','OPD',7775.07),newRecord(123,'Jordan Lim','OPD',4815),newRecord(122,'Riley Tan','ER (Emergency)',6000)];messages=[];records[2].status='Missing requirements';records[2].files=records[2].files.filter(f=>f.key!=='incident');for(let i=3;i<6;i++){const r=records[i];r.received='2026-10-03';r.reviewed=true;r.files.forEach(f=>f.checked=true);r.sentAt='2026-10-04T09:00:00+08:00';r.status=i===3?'Awaiting reply':i===4?'Approved · unpaid':'Paid';messages.push({id:'sent-'+i,caseId:r.id,direction:'Sent',subject:'Reimbursement Request | '+r.id+' | '+r.name,body:template(r),from:settings.sender,to:settings.to,cc:settings.cc,at:r.sentAt,files:r.files.map(f=>f.name),read:true,kind:'submission'});log(r,'Supporting attachments sent in a sample email.');}records[3].followup='2026-10-10';records[4].approved=4500;records[5].approved=5500;records[5].reimbursed=5475;records[5].paidDate='2026-10-09';records[5].paidBy='AMAPHIL';records[5].paymentEmail='payment-seed';messages.push({id:'approval-seed',caseId:records[4].id,direction:'Inbox',subject:'Approval | '+records[4].id,body:'Approved amount: ₱4,500.00. Please wait for the payment confirmation.',from:settings.to,to:settings.sender,at:'2026-10-08T10:00:00+08:00',files:[],read:true,kind:'approved',amount:4500});messages.push({id:'payment-seed',caseId:records[5].id,direction:'Inbox',subject:'Payment confirmation | '+records[5].id,body:'Payment completed on 9 Oct 2026. Amount reimbursed: ₱5,475.00. Processed by AMAPHIL. Approved amount: ₱5,500.00; transfer charge: ₱25.00. Fictional example only.',from:settings.to,to:settings.sender,at:'2026-10-09T10:00:00+08:00',files:['Sample payment advice.pdf'],read:true,kind:'paid',amount:5475,processor:'AMAPHIL',paymentDate:'2026-10-09'});log(records[5],'Payment confirmed from sample email: ₱5,475.00; processed by AMAPHIL; paid 9 Oct 2026.');messages.push({id:'unmatched-seed',caseId:null,direction:'Inbox',subject:'Reimbursement update',body:'Please confirm the request reference for this update.',from:settings.to,to:settings.sender,at:'2026-10-10T10:00:00+08:00',files:[],read:false,kind:'unknown'});selected=null;step=1;view='Home';statusFilter='All';search='';fromDate='';untilDate='';paused=false;}
function template(r){return settings.template.replaceAll('{{name}}',r.name).replaceAll('{{id}}',r.id).replaceAll('{{type}}',r.type).replaceAll('{{date}}',date(r.date)).replaceAll('{{amount}}',cash(r.amount)).replaceAll('{{signature}}',settings.signature);}
function gaps(r){return requirementsFor(r).filter(q=>q.required&&!r.files.some(f=>f.key===q.key&&!f.replacement));}
function ready(r){return r.reviewed&&!gaps(r).length&&r.files.every(f=>f.checked&&!f.replacement)&&requirementsFor(r).filter(q=>q.required).every(q=>r.files.some(f=>f.key===q.key&&f.selected));}
function next(r){if(r.status==='Paid')return {step:4,text:'View payment',why:'Payment confirmed'};if(r.status==='Denied')return {step:3,text:'View decision',why:'Request denied'};if(r.proposal)return {step:r.proposal.kind==='paid'?4:3,text:r.proposal.kind==='paid'?'Confirm payment':'Read reply',why:'New email to review'};if(r.status==='Approved · unpaid')return {step:4,text:'Check payment',why:'Awaiting payment confirmation'};if(r.sentAt)return {step:3,text:'View conversation',why:r.followup&&r.followup<=TODAY?'Follow-up due '+date(r.followup):'Waiting for a reply'};return {step:ready(r)?2:1,text:ready(r)?'Prepare email':'Review request',why:r.status==='Missing requirements'?'Requirements incomplete':'New request'};}
function notice(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(notice.timer);notice.timer=setTimeout(()=>$('#toast').style.display='none',4500);}
function go(v){view=v;selected=null;render();window.scrollTo(0,0);}
function openCase(id,s){selected=id;view='Request';step=s||next(current()).step;render();window.scrollTo(0,0);}
function setStep(s){const r=current();if(s===2&&!ready(r)&&!r.sentAt){notice('Finish the request and attachment checks in Step 1 first.');return;}if(s===3&&!r.sentAt){notice('Send the request in Step 2 first.');return;}if(s===4&&!['Approved · unpaid','Paid'].includes(r.status)&&r.proposal?.kind!=='paid'){notice('Review an approval or payment confirmation first.');return;}step=s;render();window.scrollTo(0,0);}
function stepState(r,n){if(n===1)return ready(r)?'Checked':'Review details and attachments';if(n===2)return r.sentAt?'Sent '+date(r.sentAt):'Choose recipients and send';if(n===3)return r.status==='Denied'?'Denied':r.approved!==null?'Approval recorded':'Track replies and follow-ups';return r.status==='Paid'?'Paid '+date(r.paidDate):'Confirm amount received';}
function sidebar(){const r=current();return `<div class="brand"><img src="logo.png" alt="RMC2"><div><strong>RMC2</strong><small>Reimbursement Monitor</small></div></div><nav class="navgroup" aria-label="Main navigation">${['Home','All requests','Emails'].map(v=>button(v,`go('${v}')`,view===v?'active':'')).join('')}</nav>${r?`<section class="steps"><p class="navlabel">This request · ${esc(r.name)}</p><nav class="navgroup" aria-label="Request progress">${['Review request','Prepare email','Replies & decision','Payment'].map((s,i)=>`<button onclick="setStep(${i+1})" class="${step===i+1?'active':''}" ${step===i+1?'aria-current="step"':''}><span class="stepnum">${i+1}</span><span>${s}<small>${stepState(r,i+1)}</small></span></button>`).join('')}${button('Activity & notes',"step=5;render()",step===5?'active':'')}</nav></section>`:''}<nav class="navgroup" aria-label="Other tools">${['Reports','Settings'].map(v=>button(v,`go('${v}')`,view===v?'active':'')).join('')}</nav><div class="asidebottom"><a href="compare.html">Compare earlier designs</a>${button('Reset demo','resetDialog()')}</div>`;}
function render(){$('#sidebar').innerHTML=sidebar();$('#breadcrumb').textContent=selected?'Requests / '+selected:view;const pages={'Home':home,'All requests':list,'Request':detail,'Emails':emails,'Reports':reports,'Settings':settingsPage,'New sample':newForm};$('#app').innerHTML=(pages[view]||home)();}
function totals(){return `<div class="metrics"><div class="metric"><span>Amount incurred</span><strong>${cash(records.reduce((s,r)=>s+r.amount,0))}</strong><small>From Form: Amount of Availment · all requests</small></div><div class="metric"><span>Approved amount</span><strong>${cash(records.reduce((s,r)=>s+(r.approved??0),0))}</strong><small>Confirmed approvals · includes paid requests</small></div><div class="metric"><span>Amount reimbursed</span><strong>${cash(records.reduce((s,r)=>s+(r.reimbursed??0),0))}</strong><small>Confirmed payments only</small></div></div>`;}
function requestTable(rs){return `<div class="tablewrap"><table><thead><tr><th>Client / request</th><th>Availment</th><th>Amount incurred</th><th>Approved</th><th>Reimbursed</th><th>Status / action</th></tr></thead><tbody>${rs.map(r=>{const n=next(r);return `<tr><td data-label="Client"><div>${button(esc(r.name),`openCase('${r.id}')`,'link')}<small>${r.id}</small></div></td><td data-label="Availment"><div>${esc(r.type)}<small>${date(r.date)}</small></div></td><td class="amount" data-label="Incurred">${cash(r.amount)}</td><td class="amount" data-label="Approved">${r.approved===null?'—':cash(r.approved)}</td><td class="amount" data-label="Reimbursed"><div>${r.reimbursed===null?'—':cash(r.reimbursed)}${r.paidBy?`<small>${esc(r.paidBy)} · ${date(r.paidDate)}</small>`:''}</div></td><td data-label="Next step"><div>${badge(r.status)}<span class="attention">${esc(n.why)}</span>${button(n.text,`openCase('${r.id}',${n.step})`)}</div></td></tr>`;}).join('')||'<tr><td colspan="6" class="empty">No requests match this view.</td></tr>'}</tbody></table></div>`;}
function home(){return `<div class="heading"><div><h1>Reimbursement monitoring</h1><p class="muted">Open a request and follow the numbered steps on the side.</p></div>${button('Add sample request',"go('New sample')",'primary')}</div>${totals()}<div class="sectionhead"><h2>Requests to work on</h2><small>Demo date: ${date(TODAY)}</small></div><div class="stats">${['All','New request','Missing requirements','Awaiting reply','Approved · unpaid','Paid'].map(s=>button(`${s==='All'?'All requests':s} · ${records.filter(r=>s==='All'||r.status===s).length}`,`statusFilter='${s}';render()`,statusFilter===s?'active':'')).join('')}</div>${requestTable(records.filter(r=>statusFilter==='All'||r.status===statusFilter))}<p class="muted"><small>Amounts and people are fictional. A blank approved or reimbursed amount means it has not been confirmed.</small></p>`;}
function list(){return `<div class="heading"><div><h1>All requests</h1><p class="muted">Search by client, reference, or type of availment.</p></div>${button('Download CSV','exportCSV()')}</div><div class="filters"><label>Search<input id="search" value="${esc(search)}" oninput="search=this.value;refreshList()"></label><label>Status<select id="status" onchange="statusFilter=this.value;refreshList()">${['All',...Object.keys(statusColors)].map(s=>`<option ${s===statusFilter?'selected':''}>${s}</option>`).join('')}</select></label><label>Received from<input type="date" id="fromdate" value="${fromDate}" onchange="fromDate=this.value;refreshList()"></label><label>Received through<input type="date" id="untildate" value="${untilDate}" onchange="untilDate=this.value;refreshList()"></label></div><p id="dateerror" class="error" role="alert"></p><div id="results">${requestTable(filtered())}</div>`;}
function filtered(){return records.filter(r=>(statusFilter==='All'||r.status===statusFilter)&&(r.id+' '+r.name+' '+r.type).toLowerCase().includes(search.toLowerCase())&&(!fromDate||r.received>=fromDate)&&(!untilDate||r.received<=untilDate));}function refreshList(){$('#dateerror').textContent=fromDate&&untilDate&&fromDate>untilDate?'Received from must be on or before Received through.':'';$('#results').innerHTML=requestTable(filtered());}
function summary(r){return `<section class="panel"><div class="facts"><div><span>Type of availment</span><strong>${esc(r.type)}</strong></div><div><span>Date of availment</span><strong>${date(r.date)}</strong></div><div><span>Request received</span><strong>${date(r.received)}</strong></div><div><span>Last updated</span><strong>${time(r.updated)}</strong></div></div><div class="facts recordmoney"><div><span>Amount incurred · Form</span><strong>${cash(r.amount)}</strong></div><div><span>Approved amount</span><strong>${cash(r.approved)}</strong></div><div><span>Amount reimbursed · paid</span><strong>${cash(r.reimbursed)}</strong></div></div></section>`;}
function detail(){const r=current();return `<div class="heading"><div><h1>${esc(r.name)}</h1><small>${r.id} · ${r.provider}</small></div>${badge(r.status)}</div>${summary(r)}${step===1?review(r):step===2?compose(r):step===3?conversation(r):step===4?payment(r):activity(r)}`;}
function review(r){const missing=gaps(r),unchecked=r.files.filter(f=>!f.checked||f.replacement).length;return `<div class="stepintro"><h2>1. Review request</h2><p>Check the application and its attachments here. Then continue to the email.</p></div><section class="panel"><h3>Application details</h3><div class="facts"><div><span>Facility</span><strong>${esc(r.facility)}</strong></div><div><span>Applicant email</span><strong>${esc(r.email)}</strong></div></div><p><strong>Reason for reimbursement</strong><br>${esc(r.reason)}</p><label class="check"><input type="checkbox" ${r.reviewed?'checked':''} onchange="confirmDetails(this.checked)">I have checked the applicant details, availment date, and amount incurred.</label><details><summary>Which requirements apply to this request?</summary><p class="muted">The Form’s OPD category does not distinguish consultation, laboratory, and medicines. Confirm these details before sending.</p>${[['laboratory','Includes laboratory / diagnostic procedures'],['medicines','Includes outpatient medicines'],['accident','Related to an accident']].map(([k,l])=>`<label class="check"><input type="checkbox" ${r[k]?'checked':''} onchange="setCondition('${k}',this.checked)">${l}</label>`).join('')}</details></section><section class="panel"><div class="sectionhead"><h3>Requirements & attached files</h3><small>${r.files.filter(f=>f.checked&&!f.replacement).length} / ${r.files.length} files checked</small></div><p class="muted">Each upload from the Form is a separate attachment. Open it here, check it, and choose whether to include it in the email.</p>${requirementsFor(r).filter(q=>q.required||r.files.some(f=>f.key===q.key)).map(q=>requirementRow(r,q)).join('')}<details><summary>Other requirements in the supplied claim form</summary>${requirementsFor(r).filter(q=>!q.required&&!r.files.some(f=>f.key===q.key)).map(q=>`<p><strong>${q.title}</strong><br><small>${q.source} Not selected for this sample’s circumstances.</small></p>`).join('')}<p><small>The supplied 2023 form also mentions original documents, filing within 30 days, and standard processing of 15 working days after complete documents. These are reference notes, not an automatic eligibility decision or promised payout date.</small></p></details></section><div class="footeractions"><div><strong>${ready(r)?'Ready to prepare the email':`${missing.length} missing requirement(s) · ${unchecked} unchecked file(s)`}</strong><small>${r.reviewed?'Application details checked.':'Check the application details above.'}</small></div>${button('Continue to email','setStep(2)','primary',!ready(r))}</div>${missing.length||r.files.some(f=>f.replacement)?button('Request missing requirements',"specialEmail('requirements')"):''}`;}
function requirementRow(r,q){const fs=r.files.map((f,i)=>({f,i})).filter(x=>x.f.key===q.key);return `<div class="req"><div class="reqhead"><div><strong>${q.title}</strong><br><small>${q.source}</small></div><span class="badge ${fs.length?'sent':'missing'}">${fs.length?fs.length+' attached':'Missing'}</span></div><div class="files">${fs.map(({f,i})=>`<div class="file"><div><strong>${esc(f.name)}</strong><small>${f.replacement?'Needs replacement':f.checked?'Checked':'Not checked'} · Form attachment</small></div><div class="row start">${button(f.checked?'View / edit check':'Open & check',`inspect(${i})`)}${f.replacement?button('Add sample replacement',`replaceFile(${i})`):''}</div></div>`).join('')||button('Add sample attachment',`addFile('${q.key}')`)}</div></div>`;}
function confirmDetails(v){current().reviewed=v;log(current(),v?'Application details checked.':'Application details marked for another review.');render();}
function setCondition(k,v){current()[k]=v;log(current(),'Requirement applicability updated: '+k+' = '+v+'.');render();}
function modal(title,body){$('#modalbody').innerHTML=`<div class="modalhead"><h2>${title}</h2>${button('Close','closeModal()')}</div>${body}`;if(!$('#modal').open)$('#modal').showModal();}function closeModal(){$('#modal').close();}
function inspect(i){const r=current(),f=r.files[i];modal(esc(f.name),`<small>Attachment ${i+1} of ${r.files.length} · ${esc(requiredSpecs.find(q=>q[0]===f.key)[1])}</small><div class="previewpaper"><div class="watermark">FICTIONAL ATTACHMENT · NOT A REAL MEDICAL RECORD</div><strong>${esc(f.name)}</strong><p>Applicant: ${esc(r.name)}<br>Availment: ${date(r.date)}<br>Reference: ${r.id}</p><p>Sample preview only. In the connected system, the original image or PDF from Drive opens here.</p></div><label class="check"><input id="include" type="checkbox" ${f.selected?'checked':''} onchange="current().files[${i}].selected=this.checked">Include this attachment in the outgoing email</label><div class="row start">${button('Mark checked',`checkFile(${i})`,'primary')}${button('Needs replacement',`flagFile(${i})`)}</div>`);}
function checkFile(i){let r=current(),f=r.files[i];f.checked=true;f.replacement=false;log(r,'Checked attachment: '+f.name);closeModal();if(r.status==='Missing requirements'&&!gaps(r).length&&r.files.every(f=>f.checked&&!f.replacement))r.status=r.sentAt?'Under review':'New request';render();notice('Attachment checked.');}
function flagFile(i){let r=current(),f=r.files[i];f.checked=false;f.selected=false;f.replacement=true;r.status='Missing requirements';log(r,'Replacement needed: '+f.name);closeModal();render();}
function replaceFile(i){const f=current().files[i];f.replacement=false;f.checked=false;f.selected=true;log(current(),'Sample replacement received: '+f.name);render();inspect(i);}
function addFile(k){let r=current(),title=requiredSpecs.find(q=>q[0]===k)[1];r.files.push({key:k,name:title.replaceAll('/','-')+' (sample).pdf',checked:false,replacement:false,selected:true});log(r,'Sample attachment received: '+title);render();inspect(r.files.length-1);}
function ensureDraft(r){if(!r.draft)r.draft={purpose:'submission',to:settings.to,cc:settings.cc,subject:'Reimbursement Request | '+r.id+' | '+r.name,body:template(r),saved:false};return r.draft;}
function compose(r){const d=ensureDraft(r);return `<div class="stepintro"><h2>2. Prepare email</h2><p>Review the recipients, message, and attachments before sending.</p></div>${r.sentAt?'<div class="callout">A request was already sent. You can prepare a follow-up or additional requirements email.</div>':''}<section class="panel"><small>From: ${esc(settings.sender)} · simulated Gmail account</small><div class="fields"><label>To<input id="to" value="${esc(d.to)}" oninput="current().draft.to=this.value"><small>Separate multiple addresses with commas.</small></label><label>CC<input id="cc" value="${esc(d.cc)}" oninput="current().draft.cc=this.value"></label></div><label>Template<select onchange="chooseTemplate(this.value)">${[['submission','Reimbursement request'],['followup','Follow-up'],['requirements','Missing requirements']].map(([v,l])=>`<option value="${v}" ${d.purpose===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Subject<input id="subject" value="${esc(d.subject)}" oninput="current().draft.subject=this.value"></label><label>Message<textarea id="body" rows="14" oninput="current().draft.body=this.value">${esc(d.body)}</textarea></label><h3>Attachments to send (${r.files.filter(f=>f.selected).length})</h3>${r.files.map((f,i)=>`<label class="check"><input type="checkbox" ${f.selected?'checked':''} ${f.replacement?'disabled':''} onchange="current().files[${i}].selected=this.checked">${esc(f.name)} · ${f.checked&&!f.replacement?'Checked':'Needs checking'}</label>`).join('')}<small>These are separate attachments. The example email shows one PDF; this prototype does not combine files into a PDF.</small><p id="senderror" class="error" role="alert"></p><div class="footeractions">${button('Back to review','setStep(1)')}<div class="row start">${button('Save draft','saveDraft()')}${button('Preview & send','previewSend()','primary')}</div></div></section>`;}
function chooseTemplate(p){const r=current(),d=ensureDraft(r);d.purpose=p;d.subject=(p==='submission'?'Reimbursement Request':p==='followup'?'Follow-up':'Additional requirements')+' | '+r.id+' | '+r.name;d.body=p==='submission'?template(r):p==='followup'?`Good Day!\n\nHi All,\n\nMay we request an update on the reimbursement for ${r.name}?\nReference: ${r.id}\n\nThank you.\n${settings.signature}`:`Good Day!\n\nPlease provide the missing or corrected requirements for ${r.name} (${r.id}):\n${requirementsFor(r).filter(q=>q.required&&(!r.files.some(f=>f.key===q.key)||r.files.some(f=>f.key===q.key&&f.replacement))).map(q=>'- '+q.title).join('\n')}\n\nThank you.\n${settings.signature}`;if(p==='requirements')d.to=r.email;else d.to=settings.to;d.saved=false;render();}
function specialEmail(p){ensureDraft(current());step=2;chooseTemplate(p);if(p==='requirements')current().files.forEach(f=>f.selected=false);render();}
function saveDraft(){ensureDraft(current()).saved=true;log(current(),'Email draft saved in this demo session.');notice('Draft saved. Find it under Emails / Drafts.');}
const validAddresses=s=>s.split(/[,;]/).map(x=>x.trim()).filter(Boolean).every(x=>/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(x));
function sendError(){const r=current(),d=ensureDraft(r);if(['Paid','Denied'].includes(r.status))return 'This request is closed. Its status and financial history are preserved.';if(!d.to.trim()||!validAddresses(d.to)||!validAddresses(d.cc))return 'Enter valid recipient addresses, separated by commas.';if(!d.subject.includes(r.id))return 'Keep the reimbursement ID in the subject.';if(!d.body.trim())return 'Enter the message.';if(r.files.some(f=>f.selected&&(!f.checked||f.replacement)))return 'Check every selected attachment in Step 1.';if(d.purpose==='submission'&&!ready(r))return 'Complete the application checks and include each required attachment category.';return '';}
function previewSend(){const err=sendError();if(err){$('#senderror').textContent=err;return;}let r=current(),d=r.draft;modal('Confirm outgoing email',emailHTML({subject:d.subject,from:settings.sender,to:d.to,cc:d.cc,body:d.body,at:stamp(),files:r.files.filter(f=>f.selected).map(f=>f.name),direction:'Draft'})+button('Send demo email','sendDemo()','primary'));}
function sendDemo(){const err=sendError();if(err){closeModal();render();$('#senderror').textContent=err;return;}let r=current(),d=r.draft,at=stamp();messages.unshift({id:'msg-'+clock,caseId:r.id,direction:'Sent',subject:d.subject,body:d.body,to:d.to,cc:d.cc,from:settings.sender,at,files:r.files.filter(f=>f.selected).map(f=>f.name),read:true,kind:d.purpose});if(d.purpose==='submission'){r.sentAt=r.sentAt||at;r.status='Awaiting reply';}r.followup='2026-10-14';log(r,'Sent sample '+d.purpose+' email with '+r.files.filter(f=>f.selected).length+' attachment(s).');r.draft=null;closeModal();step=r.sentAt?3:1;render();notice('Demo email recorded. No real message was sent.');}
function emailHTML(m){return `<article class="email"><div class="row"><h3>${esc(m.subject)}</h3><span class="badge sent">${esc(m.direction)}</span></div><small>${time(m.at)} · Philippine time<br>From: ${esc(m.from)}<br>To: ${esc(m.to)}${m.cc?'<br>CC: '+esc(m.cc):''}</small><pre>${esc(m.body)}</pre><div class="attachments">${m.files.map(f=>`<span class="attachment">${esc(f)}</span>`).join('')}</div></article>`;}
function conversation(r){const ms=messages.filter(m=>m.caseId===r.id).sort((a,b)=>b.at.localeCompare(a.at));ms.forEach(m=>m.read=true);return `<div class="stepintro"><h2>3. Replies & decision</h2><p>Read the department’s response. Confirm the approval amount before moving to payment.</p></div>${r.proposal?`<div class="callout warn"><strong>${r.proposal.kind==='paid'?'Payment email received':r.proposal.kind==='approved'?'Approval needs confirmation':'Reply needs review'}</strong><p>Read the email below. Financial details are not saved until you confirm them.</p>${button(r.proposal.kind==='paid'?'Review payment':'Review decision',r.proposal.kind==='paid'?'setStep(4)':'decisionDialog()','primary')}</div>`:''}<div class="panel"><div class="row"><div><h3>Follow-up</h3><small>${r.followup?'Scheduled for '+date(r.followup):'No reminder scheduled'}</small></div><div class="row start">${button('Set reminder','reminderDialog()')}${button('Write follow-up',"specialEmail('followup')")}${button('Add sample reply','replyDialog()')}</div></div></div>${ms.map(emailHTML).join('')||'<div class="empty">No emails yet.</div>'}${r.status==='Approved · unpaid'?button('Continue to payment','setStep(4)','primary'):''}`;}
function replyDialog(){modal('Add a sample reply',`<p>Choose a fictional email scenario. A suggestion will appear for confirmation.</p><label>Reply type<select id="replykind"><option value="received">Acknowledgement</option><option value="approved">Approval</option><option value="missing">Missing requirements</option><option value="denied">Denied</option><option value="paid">Payment confirmation</option></select></label><label>Amount in email (approval or payment)<input id="replyamount" type="number" min="0.01" step="0.01" value="${current().approved??current().amount}"></label><label>Payment processed by<select id="replyprocessor"><option>AMAPHIL</option><option>RMC2</option></select></label>${button('Receive sample email','receiveReply()','primary')}<p id="replyerror" class="error" role="alert"></p>`);}
function receiveReply(){const r=current(),kind=$('#replykind').value,amount=Number($('#replyamount').value),processor=$('#replyprocessor').value;if(['approved','paid'].includes(kind)&&(!Number.isFinite(amount)||amount<=0)){$('#replyerror').textContent='Enter a positive amount from the sample email.';return;}const id='msg-'+(clock++),body={received:'We have received your reimbursement request and are evaluating it.',approved:`The request has been approved. Approved amount: ${cash(amount)}. Please wait for disbursement.`,missing:'Please provide a clearer official receipt with BIR TIN before further processing.',denied:'This sample claim was denied. Please contact the department for the reason and further clarification.',paid:`Payment confirmation for ${r.id}.\nAmount reimbursed: ${cash(amount)}\nPayment date: ${date(TODAY)}\nProcessed by: ${processor}\nPlease see the payment advice. Fictional sample only.`}[kind];messages.unshift({id,caseId:r.id,direction:'Inbox',subject:'Re: Reimbursement Request | '+r.id,body,from:processor==='RMC2'&&kind==='paid'?'accounting@example.com':settings.to,to:settings.sender,at:stamp(),files:kind==='paid'?['Sample payment advice.pdf']:[],read:false,kind,amount:['approved','paid'].includes(kind)?amount:null,processor:kind==='paid'?processor:null,paymentDate:kind==='paid'?TODAY:null});if(!paused)r.proposal={kind,emailId:id};else messages[0].pendingCheck=true;log(r,'Sample '+kind+' email received; '+(paused?'checks paused.':'awaiting review.'));closeModal();step=kind==='paid'?4:3;render();}
function decisionDialog(){const r=current(),p=r.proposal;if(!p)return;const m=messages.find(m=>m.id===p.emailId);if(p.kind==='paid'){step=4;render();return;}modal('Confirm decision from email',emailHTML(m)+`<label>Decision<select id="decision">${[['received','Under review'],['approved','Approved · unpaid'],['missing','Missing requirements'],['denied','Denied']].map(([v,l])=>`<option value="${v}" ${p.kind===v?'selected':''}>${l}</option>`).join('')}</select></label><label>Approved amount (required for approval)<input id="approvedamount" type="number" step="0.01" min="0.01" value="${m.kind==='approved'?m.amount:''}"></label><label>Decision note<textarea id="decisionnote" style="min-height:80px" placeholder="Reason or clarification"></textarea></label>${button('Confirm decision','confirmDecision()','primary')}<p id="decisionerror" class="error" role="alert"></p>`);}
function confirmDecision(){const r=current(),v=$('#decision').value,amount=Number($('#approvedamount').value),why=$('#decisionnote').value.trim();if(r.status==='Paid'){$('#decisionerror').textContent='Payment is already recorded. This reply cannot overwrite a paid request.';return;}if(v==='approved'&&(!Number.isFinite(amount)||amount<=0)){$('#decisionerror').textContent='Enter the approved amount stated in the email.';return;}if(v==='denied'&&!why){$('#decisionerror').textContent='Record the denial reason from the email.';return;}r.status={received:'Under review',approved:'Approved · unpaid',missing:'Missing requirements',denied:'Denied'}[v];if(v==='approved')r.approved=amount;if(v==='missing'){const f=r.files.find(f=>f.key==='receipt');if(f){f.checked=false;f.replacement=true;f.selected=false;}}if(v==='denied'){r.approved=null;r.followup=null;}log(r,'Confirmed '+r.status+(v==='approved'?' · approved '+cash(amount):'')+' from email '+r.proposal.emailId+(why?': '+why:'.'));r.proposal=null;closeModal();step=v==='missing'?1:3;render();}
function payment(r){const source=messages.find(m=>m.id===(r.proposal?.kind==='paid'?r.proposal.emailId:r.paymentEmail));const candidates=messages.filter(m=>m.caseId===r.id&&m.direction==='Inbox'&&m.kind==='paid');return `<div class="stepintro"><h2>4. Payment</h2><p>Use the payment email to confirm the amount reimbursed, payment date, and who processed it.</p></div>${r.status==='Paid'?`<div class="callout success"><strong>Payment recorded: ${cash(r.reimbursed)}</strong><p>Paid ${date(r.paidDate)} · Processed by ${esc(r.paidBy)}</p><small>Approved: ${cash(r.approved)}. ${r.approved!==null?'Difference: '+cash(r.approved-r.reimbursed)+'. Differences are not automatically treated as fees.':''}</small></div>`:`<div class="callout ${candidates.length?'warn':''}"><strong>${candidates.length?'Payment confirmation is ready for review':'Waiting for a payment confirmation'}</strong><p>Approval does not mark this request as paid. The amount reimbursed stays blank until you confirm the payment.</p></div>`}${source?emailHTML(source):candidates.map(emailHTML).join('')}<section class="panel"><div class="row"><div><h3>${r.status==='Paid'?'Payment evidence':'Record payment from an email'}</h3><small>${r.status==='Paid'?'See the linked email above and the activity history.':'Nothing is extracted from a live mailbox in this prototype.'}</small></div><div class="row start">${button('Add sample payment email',"replyDialog();document.querySelector('#replykind').value='paid'")}${r.status!=='Paid'?button('Confirm payment','paymentDialog()','primary',!candidates.length):''}</div></div></section>${button('View activity & notes','step=5;render()')}`;}
function paymentDialog(){const r=current(),ms=messages.filter(m=>m.caseId===r.id&&m.direction==='Inbox'&&m.kind==='paid');if(!ms.length)return;const m=ms.find(m=>m.id===r.proposal?.emailId)||ms[0];modal('Confirm payment details',`<p>Values below come from the selected sample email. Verify them before saving.</p><label>Payment email<select id="payemail" onchange="fillPayment(this.value)">${ms.map(x=>`<option value="${x.id}" ${x.id===m.id?'selected':''}>${esc(x.subject)} · ${time(x.at)}</option>`).join('')}</select></label><label>Amount reimbursed<input id="payamount" type="number" min="0.01" step="0.01" value="${m.amount??''}"></label><div class="fields"><label>Payment date<input id="paydate" type="date" min="${r.received}" max="${TODAY}" value="${m.paymentDate||''}"></label><label>Processed by<select id="payprocessor"><option value="">Choose processor</option>${['AMAPHIL','RMC2'].map(x=>`<option ${x===m.processor?'selected':''}>${x}</option>`).join('')}</select></label></div><label>Payment note<textarea id="paynote" style="min-height:75px" placeholder="Explain any difference from the approved amount"></textarea></label><p id="payerror" class="error" role="alert"></p>${button('Confirm & mark paid','confirmPayment()','primary')}`);}
function fillPayment(id){const m=messages.find(x=>x.id===id);$('#payamount').value=m.amount??'';$('#paydate').value=m.paymentDate||'';$('#payprocessor').value=m.processor||'';}
function confirmPayment(){const r=current(),amount=Number($('#payamount').value),paidDate=$('#paydate').value,processor=$('#payprocessor').value,evidence=$('#payemail').value,note=$('#paynote').value.trim();let err='';if(r.status==='Paid')err='Payment is already recorded.';else if(!Number.isFinite(amount)||amount<=0)err='Enter the amount actually reimbursed.';else if(!paidDate||paidDate<r.received||paidDate>TODAY)err='Payment date must be between receipt of the request and the demo date.';else if(!['AMAPHIL','RMC2'].includes(processor))err='Choose who processed this payment.';else if(!messages.some(m=>m.id===evidence&&m.caseId===r.id&&m.kind==='paid'))err='Choose a payment email for this request.';else if(r.approved!==null&&amount!==r.approved&&!note)err='Explain the difference from the approved amount using the payment email.';if(err){$('#payerror').textContent=err;return;}r.reimbursed=amount;r.paidDate=paidDate;r.paidBy=processor;r.paymentEmail=evidence;r.status='Paid';r.followup=null;r.proposal=null;log(r,`Payment confirmed: ${cash(amount)}; paid ${date(paidDate)}; processed by ${processor}; evidence ${evidence}.${note?' '+note:''}`);closeModal();render();notice('Payment recorded with the amount, processor, date, and email evidence.');}
function reminderDialog(){modal('Set follow-up reminder',`<label>Follow-up date<input id="reminder" type="date" min="${TODAY}" value="${current().followup||'2026-10-14'}"></label>${button('Save reminder','saveReminder()','primary')} ${button('Remove reminder',"current().followup=null;log(current(),'Follow-up reminder removed.');closeModal();render()")}`);}
function saveReminder(){const v=$('#reminder').value;if(!v||v<TODAY){notice('Choose the demo date or a later date.');return;}current().followup=v;log(current(),'Follow-up scheduled for '+date(v));closeModal();render();}
function activity(r){return `<div class="stepintro"><h2>Activity & notes</h2><p>Every confirmed change is recorded with its date and time.</p></div><section class="panel notebox"><label>Add a note<textarea id="note"></textarea></label>${button('Save note','saveNote()')}${r.notes.map(n=>`<p>${esc(n)}</p>`).join('')}</section><section class="panel"><h3>History · Philippine time</h3><div class="timeline">${r.history.map(e=>`<div class="event"><small>${time(e.at)}</small>${esc(e.text)}</div>`).join('')}</div></section>`;}
function saveNote(){const v=$('#note').value.trim();if(!v)return;current().notes.unshift(v);log(current(),'Note added: '+v);render();}
function emails(){const ms=messages.filter(m=>mailFilter==='Needs matching'?!m.caseId:mailFilter==='Sent'?m.direction==='Sent':m.direction==='Inbox'&&m.caseId).sort((a,b)=>b.at.localeCompare(a.at));const m=ms.find(m=>m.id===picked)||ms[0];return `<div class="heading"><div><h1>Emails</h1><p class="muted">One demo mailbox · ${esc(settings.sender)}</p></div>${button(paused?'Resume demo checks':'Pause demo checks','toggleChecks()')}</div><div class="callout">${paused?'Demo checks paused.':'Demo only. No Gmail account connected.'} Real reply retrieval and automatic matching are not active.</div><div class="stats">${['Inbox','Sent','Drafts','Needs matching'].map(s=>button(s,`mailFilter='${s}';picked=null;render()`,mailFilter===s?'active':'')).join('')}</div>${mailFilter==='Drafts'?records.filter(r=>r.draft?.saved).map(r=>`<section class="panel"><h3>${esc(r.draft.subject)}</h3>${button('Open draft',`openCase('${r.id}',2)`)}</section>`).join('')||'<div class="empty">No saved drafts.</div>':`<div class="split"><section>${ms.map(x=>`<button class="mailitem ${x.id===m?.id?'active':''}" onclick="picked='${x.id}';render()">${esc(x.subject)}<small>${time(x.at)}</small></button>`).join('')||'<div class="empty">No emails in this view.</div>'}</section><section>${m?emailHTML(m)+(m.caseId?button('Open request',`openCase('${m.caseId}',${m.kind==='paid'?4:3})`,'primary'):button('Link to request',`matchDialog('${m.id}')`,'primary')):''}</section></div>`}`;}
function toggleChecks(){paused=!paused;if(!paused){messages.filter(m=>m.pendingCheck).reverse().forEach(m=>{const r=records.find(r=>r.id===m.caseId);if(r)r.proposal={kind:m.kind,emailId:m.id};m.pendingCheck=false;});}render();}
function matchDialog(id){modal('Link email to request',`<p>Choose the correct request after reading the email. Linking will not change its status.</p><label>Request<select id="match">${records.map(r=>`<option value="${r.id}">${esc(r.name)} · ${r.id}</option>`).join('')}</select></label>${button('Confirm link',`matchMessage('${id}')`,'primary')}`);}
function matchMessage(id){const m=messages.find(m=>m.id===id);m.caseId=$('#match').value;log(records.find(r=>r.id===m.caseId),'Manually linked email '+id+'. Status unchanged.');closeModal();render();}
function reports(){return `<div class="heading"><div><h1>Reports</h1><p class="muted">Incurred, approved, and paid totals are separate.</p></div>${button('Download CSV','exportCSV()')}</div>${totals()}${requestTable(records)}`;}
function exportCSV(){const cell=v=>'"'+String(v??'').replaceAll('"','""')+'"',rows=[['Reference','Client','Provider','Type of availment','Date of availment','Amount incurred','Approved amount','Amount reimbursed','Status','Payment date','Processed by','Payment email','Received','Sent','Follow-up date'],...records.map(r=>[r.id,r.name,r.provider,r.type,r.date,r.amount,r.approved,r.reimbursed,r.status,r.paidDate,r.paidBy,r.paymentEmail,r.received,r.sentAt,r.followup])];const u=URL.createObjectURL(new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=u;a.download='RMC2-monitoring-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);}
function settingsPage(){return `<h1>Settings</h1><p class="muted">Demo recipients and templates. Changes last until the page is refreshed.</p><section class="panel"><div class="fields"><label>Department recipients<input id="settingto" value="${esc(settings.to)}"></label><label>Default CC<input id="settingcc" value="${esc(settings.cc)}"></label></div><label>Signature<input id="signature" value="${esc(settings.signature)}"></label><label>Reimbursement email template<textarea id="template" rows="12">${esc(settings.template)}</textarea></label><small>Fields: {{name}}, {{id}}, {{type}}, {{date}}, {{amount}}, {{signature}}</small><p id="settingerror" class="error"></p>${button('Save demo settings','saveSettings()','primary')}</section><section class="panel"><h3>Connections</h3><p>Google Forms, Sheets, Drive, and Gmail are not connected. All request and payment messages are simulated.</p><p>For the planned connection, every Drive link in the six attachment columns becomes an individual file under its requirement. File names without working links need manual attention.</p></section>`;}
function saveSettings(){const to=$('#settingto').value.trim(),cc=$('#settingcc').value.trim();if(!to||!validAddresses(to)||!validAddresses(cc)){$('#settingerror').textContent='Enter valid email addresses separated by commas.';return;}settings.to=to;settings.cc=cc;settings.signature=$('#signature').value;settings.template=$('#template').value;notice('Demo settings saved.');}
function newForm(){return `<div class="heading"><div><h1>Add a sample Form submission</h1><p class="muted">Use fictional information to try the complete workflow.</p></div></div><form id="newform" class="panel"><div class="fields"><label>Client name<input name="name" value="Avery Flores" required></label><label>Applicant email<input type="email" name="email" value="avery@example.com" required></label><label>Type of availment<select name="type"><option>OPD</option><option>ER (Emergency)</option><option>ADMISSION</option></select></label><label>Date of availment<input name="date" type="date" value="2026-10-08" max="${TODAY}" required></label><label>Amount incurred<input name="amount" type="number" step="0.01" min="0.01" value="6200" required><small>Maps to “Amount of Availment” in the Form.</small></label><label>Facility<input name="facility" value="Sample Medical Center" required></label></div><p>Applicable sample attachments will be added. No private Drive files are imported.</p><button class="primary" type="submit">Create sample request</button></form>`;}
document.addEventListener('submit',e=>{if(e.target.id!=='newform')return;e.preventDefault();const f=new FormData(e.target);const n=Math.max(...records.map(r=>Number(r.id.split('-').pop())))+1,r=newRecord(n,f.get('name'),f.get('type'),Number(f.get('amount')));r.email=f.get('email');r.date=f.get('date');r.facility=f.get('facility');records.unshift(r);openCase(r.id,1);});
function resetDialog(){modal('Reset sample data?',`<p>This clears this session’s practice changes and restores the fictional requests.</p>${button('Reset demo',"seed();closeModal();render()",'primary')}`);}
seed();render();
